CREATE TABLE CORE.T_FACT_GOODS_MOVEMENT_2 (
   WSHOP_CD                            VARCHAR(5)      COMMENT 'The unique code for the Lidl webshop, where an order can be placed by a customer.The webshop is defined per political country_2 and is run by an Lidl Digital Country_2',
   DIST_CHANNEL_CD                     VARCHAR(5)      COMMENT 'The code for the distribution channel ( a channel  through which the goods are sold )',
   DELIVERY_ORDER_SID                  NUMBER          NOT NULL COMMENT 'The unique identifier (surrogate key) for delivery order ',
   DELIVERY_ORDER_NR                   VARCHAR(20)     NOT NULL COMMENT 'Delivery order number ',
   DELIVERY_ORDER_POS_NR               NUMBER          NOT NULL COMMENT 'The particular position number of a position in an order',
   GOODS_MOV_CAT_CD                    VARCHAR(10)     COMMENT 'The code which identifies the reason why a product is moved out of the warehouse. E.g. delivery to a customer, return to a supplier_2, movement to another warehouse, ...',
   GOODS_MOV_CAT_GROUP_CD              VARCHAR(10)     COMMENT 'The code which identifies the reason why a product is moved out of the warehouse. E.g. delivery to a customer, return to a supplier_2, movement to another warehouse, ...',
   GOODS_MOV_ORIG_TMSP                 TIMESTAMP_TZ(9) COMMENT 'The original goods movement timestamp of the order. In case the order gets split because the ordered items cannot fit in one package_2, there will be a difference between goods_mov_orig_tmsp and goods_mov_actual_tmsp. Otherwise, goods_mov_orig_tmsp should be the same as goods_mov_actual_tmsp.',
   GOODS_MOV_ACTUAL_TMSP               TIMESTAMP_TZ(9) COMMENT 'The actual goods movement timestamp based on the category',
   DELIVERY_ADDR_SID                   NUMBER          COMMENT 'The unique identifier (sk) for the delivery address_2 where original order was delivered',
   PROD_VARIANT_SID                    NUMBER          COMMENT 'The unique identifier (surrogate key) for the product variant',
   PROD_VARIANT_NR                     VARCHAR(20)     COMMENT 'The product variant number',
   DELIVERY_PROD_QTY                   NUMBER(38, 5)   COMMENT 'The number of products that are to be delivered',
   DELIVERY_TYPE_CD                    VARCHAR(5)      COMMENT 'The code to identify the delivery type',
   DELIVERY_ROUTE_CD                   VARCHAR(50)     COMMENT 'The code to identify delivery route',
   RECIPIENT_COUNTRY_CD                VARCHAR(5)      COMMENT 'The recipient country_2 code',
   STOCK_PLACEMENT_CD                  VARCHAR(10)     COMMENT 'The code which identifies the storage type indicator for stock placement.',
   STOCK_REMOVAL_CD                    VARCHAR(10)     COMMENT 'The code which identifies the storage type indicator for stock removal.',
   ORDER_ITEM_CATEGORY_CD              VARCHAR(5)      COMMENT 'The code to uniquely identify the order item_2 categories',
   CUST_ORDER_SID                      NUMBER          COMMENT 'The unique identifier (surrogate key) for customer order',
   CUST_ORDER_POS_NR                   NUMBER          COMMENT 'The particular position number of an item_2 in an order',
   CUST_ORDER_NR                       VARCHAR(20)     COMMENT 'The original order number of the source system',
   CUST_SID                            NUMBER          COMMENT 'The unique identifier (surrogate key) for the customer',
   WH_SID                              NUMBER          COMMENT 'The unique identifier (surrogate key) for the warehouse',
   WH_CD                               VARCHAR(5)      COMMENT 'A short unique code for the warehouses which receives the deliveries',
   SENDER_WH_CD                        VARCHAR(5)      COMMENT 'A short unique code for the warehouses which sends the deliveries.',
   STORAGE_LOC_CD                      VARCHAR(10)     COMMENT 'The code which identifies the storage location_2 (10001, 1002, etc)',
   SALE_DOC_TYPE_CD                    VARCHAR(5)      COMMENT 'The code for the the delivery document ( C (Order), H (Return), I (Order w/o charge), V (Purchase Order) )',
   DELIVERY_TGT_DT                     DATE            COMMENT 'First date which has been communicated to the customer until when the shipment is meant to arrive',
   WH_LEAVE_ACTUAL_TMSP                TIMESTAMP_TZ(9) COMMENT 'The timestamp when the truck actually left the warehouse platform (\"Rampe\") from which the package_2 is sent to the customer',
   WH_LEAVE_TGT_TMSP                   TIMESTAMP_TZ(9) COMMENT 'The timestamp when the truck is meant to leave for the specific tracking id. The time is known as CPT. The time depends on the warehouse, the carrier, the workday and the shipment type',
   WH_ARRIVE_ACTUAL_DT                 DATE            COMMENT 'Date on which the goods were placed in the warehouse.',
   IC_ORDER_SID                        NUMBER          COMMENT 'The unique identifier (surrogate key) for intercompany order',
   IC_ORDER_POS_NR                     NUMBER          COMMENT 'The particular position number of an item_2 in an order',
   IC_ORDER_NR                         VARCHAR(20)     COMMENT 'The order number assigned to the intercompany sale order in the source system',
   SUPPLIER_ORDER_NR                   VARCHAR(20)     COMMENT 'This field holds the document number of the reference document. In case of dropshipments, the reference document corresponds to the supplier_2 order number (purchase order number) which took place after the sales_2 order.',
   SUPPLIER_ORDER_POS_NR               NUMBER          COMMENT 'Product position number on purchase order',
   DROPSHIPMENT_ORDER_FG               BOOLEAN         COMMENT 'In case the product is being sent directly from the supplier_2 this field will be filled.',
   DWH_CREATED_TMSP                    TIMESTAMP_LTZ(9) NOT NULL COMMENT 'The point in time when this record was created in the data warehouse.',
   DWH_UPDATED_TMSP                    TIMESTAMP_LTZ(9) NOT NULL COMMENT 'The point in time when this record was last updated.',
   DWH_SRC_FILE_NAME                   VARCHAR(255)    NOT NULL COMMENT 'The path and the name of the file(s) from which this record was loaded.',
   SRC_FILE_TMSP                       TIMESTAMP_LTZ(9) NOT NULL COMMENT 'The point in time when this record was extracted from the source.',   
   CONSTRAINT PK_T_FACT_GOODS_MOVEMENT PRIMARY KEY (DELIVERY_ORDER_SID, DELIVERY_ORDER_POS_NR) NOT ENFORCED 
)  COMMENT = 'This transactional fact tracks packets that are going out /in of the warehouse ( including dropshipments)';
